from pathlib import Path
import json,hashlib
import numpy as np,pandas as pd
r=Path(__file__).resolve().parents[1];o=r/"phase29";rows=[];checks=[]
for f in sorted(o.glob("*_joint_*/s*.json")):
 d=json.loads(f.read_text());assert d["model_restored_exact"] and d["source_controller_only"];assert d["subject"] in [7,17,27,37];path=r/"phase28"/f.parent.name/"model.pt";assert hashlib.sha256(path.read_bytes()).hexdigest()==d["checkpoint_sha256"]
 rows.extend(d["rows"]);checks.append(dict(source=d["source"],weight=d["weight"],subject=d["subject"],rows=len(d["rows"])))
if not rows:raise SystemExit("No completed pulse person yet")
df=pd.DataFrame(rows);assert np.isfinite(df.select_dtypes(include="number")).all().all();assert not df.duplicated(["source","weight","subject","t","objective","lr"]).any();df.to_csv(o/"pulses.csv",index=False);people=[]
for keys,g in df.groupby(["source","weight","objective","lr","subject"]):
 people.append(dict(source=keys[0],weight=keys[1],objective=keys[2],lr=keys[3],subject=keys[4],pulses=len(g),future_ce_gain=g.future_ce_gain.mean(),current_ce_gain=g.current_ce_gain.mean(),base_ce=g.base_ce.mean(),gradient_cosine=g.gradient_cosine.mean(),beneficial_fraction=(g.future_ce_gain>1e-6).mean(),harmful_fraction=(g.future_ce_gain< -1e-6).mean(),oracle_keep_write=np.maximum(g.future_ce_gain,0).mean(),current_oracle_utility=np.where(g.current_ce_gain>0,g.future_ce_gain,0).mean()))
pd.DataFrame(people).to_csv(o/"participants.csv",index=False);summary=pd.DataFrame(people).groupby(["source","weight","objective","lr"]).agg(n_people=("subject","count"),pulses=("pulses","sum"),future_ce_gain=("future_ce_gain","mean"),current_ce_gain=("current_ce_gain","mean"),base_ce=("base_ce","mean"),gradient_cosine=("gradient_cosine","mean"),beneficial_fraction=("beneficial_fraction","mean"),harmful_fraction=("harmful_fraction","mean"),oracle_keep_write=("oracle_keep_write","mean"),current_oracle_utility=("current_oracle_utility","mean")).reset_index();summary.to_csv(o/"summary.csv",index=False)
complete=len(list(o.glob("*/complete.json")))==6;(o/"audit.json").write_text(json.dumps(dict(status="PASS",complete=complete,completed_person_cases=len(checks),pulse_rows=len(df),checks="Source-controller IDs, unique finite rows, source checkpoint SHA and exact restoration runtime assertions",details=checks),indent=2))
html="""<!doctype html><html lang="zh"><meta charset="utf-8"><title>联合训练后的写入效用</title><style>body{font:15px/1.6 system-ui;max-width:1400px;margin:30px auto}td,th{padding:5px;border-bottom:1px solid #ccc}</style><h1>联合训练后的冷启动写入诊断</h1><p>4名源控制器受试者；每人64个均匀时间点；每次独立从源参数开始，预测当前窗口之后用当前无标签熵或修正教师掩码目标更新LayerNorm。随后只用于离线诊断，比较未来4窗口的交叉熵。未来标签与未来梯度绝不进入参数更新。</p><p>future_ce_gain为正表示写入降低未来CE（单位nats），并非在线F1。oracle_keep_write使用未来标签上界；current_oracle_utility使用当前真实标签，也不是可部署策略。当前不同模型的base_ce不同，收益大小不能脱离分类器起点解释。均值先按人计算，避免窗口数当独立样本。</p>"""+f"<p>当前完成{len(checks)}/24个人模型案例，共{len(df)}条写入结果。完整：{complete}。</p>"+summary.to_html(index=False,float_format=lambda x:f"{x:.6f}")+"""<p><a href="protocol.json">固定协议</a> · <a href="participants.csv">个人结果</a> · <a href="audit.json">审计</a></p></html>""";(o/"report.html").write_text(html)
print(summary[summary.lr==.01].to_string(index=False))
